public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int source = start[0] * n + start[1];
    int destination = end[0] * n + end[1];
    if (source == destination) {
        return "can be travelled";
    }
    while (source != destination) {
        int x = source / n;
        int y = source % n;
        if ((x == 0 || x == n - 1 || y == 0 || y == n - 1)) {
            return "cannot be travelled";
        }
        if (x > 0 && paths[x - 1][y] != 0) {
            source = x * n + y;
        } else if (x < n - 1 && paths[x + 1][y] != 0) {
            source = (x + 1) * n + y;
        } else if (y > 0 && paths[x][y - 1] != 0) {
            source = x * n + (y - 1);
        } else if (y < n - 1 && paths[x][y + 1] != 0) {
            source = x * n + (y + 1);
        } else {
            return "cannot be travelled";
        }
    }
    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Create a boolean array to mark visited nodes
        boolean[][] visited = new boolean[n][n];
        // Create a queue to perform BFS
        java.util.Queue<Pair<Integer, Integer>> queue = new LinkedList<>();

        // Add the starting node to the queue
        queue.offer(new Pair<>(start[0], start[1]));
        visited[start[0]][start[1]] = true;

        // Perform BFS
        while (!queue.isEmpty()) {
            Pair<Integer, Integer> current = queue.poll();
            int x = current.getKey();
            int y = current.getValue();

            // If the current node is the end node, return "can be travelled"
            if (x == end[0] && y == end[1]) {
                return "can be travelled";
            }

            // Explore all valid adjacent nodes
            for (int[] direction : new int[][]{{1, 0}, {-1, 0}, {0, 1}, {0, -1}}) {
                int newX = x + direction[0];
                int newY = y + direction[1];

                // Check if the new coordinates are within bounds and unvisited
                if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                    queue.offer(new Pair<>(newX, newY));
                    visited[newX][newY] = true;
                }
            }
        }

        // If no route is found by the end node, return "cannot be travelled"
        return "cannot be travelled";
    }

