public static String appx(String word1, String word2) {
    int commonCount = 0;
    for (int i = 0; i < word1.length() && i < word2.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonCount++;
        }
    }
    int totalLength = word1.length() + word2.length();
    int numerator = commonCount;
    int denominator = totalLength;

    // Simplify the fraction by finding the greatest common divisor (GCD)
    for (int i = numerator; i >= 1; i--) {
        if (numerator % i == 0 && denominator % i == 0) {
            numerator /= i;
            denominator /= i;
            break;
        }
    }

    return String.format("appx(%s, %s) = %d/%d", word1, word2, numerator, denominator);
}

public static String appx(String word1, String word2) {
    if (word1.isEmpty() || word2.isEmpty()) {
        return "Error: Two words are required.";
    }

    int commonLetters = word1.chars()
                              .mapToObj(c -> (char) c)
                              .distinct()
                              .count();

    int totalLetters = word1.length() + word2.length();

    BigInteger gcd = BigInteger.valueOf(commonLetters).gcd(BigInteger.valueOf(totalLetters));
    BigInteger numerator = BigInteger.valueOf(commonLetters).divide(gcd);
    BigInteger denominator = BigInteger.valueOf(totalLetters).divide(gcd);

    if (numerator.equals(denominator)) {
        return numerator.toString() + "/" + denominator.toString();
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator.toString();
    }
}

