public static String convertDatesToWeekdays(String date) {
    String[] parts = date.split(" ");
    if (parts.length != 3 || !parts[0].matches("\\d+") || !parts[1].matches("\\d+") || !parts[2].matches("\\d+")) {
        return "Invalid date format. Please enter the date in the format 'MM dd yyyy'.";
    }

    int month = Integer.parseInt(parts[0]);
    int day = Integer.parseInt(parts[1]);
    int year = Integer.parseInt(parts[2]);

    Calendar calendar = new GregorianCalendar(year, month - 1, day);
    int dayOfWeek = calendar.get(Calendar.DAY_OF_WEEK);

    String[] daysOfWeek = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    return dayOfWeeks[dayOfWeek - 1] + ", " + month + " " + day + ", " + year;
}

public static String convertDatesToWeekdays(String date) {
        SimpleDateFormat df = new SimpleDateFormat("MM dd yyyy");

        try {
            Date originalDate = df.parse(date);
            Calendar calendar = Calendar.getInstance();
            calendar.setTime(originalDate);

            String[] weekDays = {"Saturday", "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday"};
            String weekday = weekDays[calendar.get(Calendar.DAY_OF_WEEK) - 1]; // Adjusting for 1-based index

            return weekday + ", " + df.format(originalDate);
        } catch (ParseException e) {
            return "Invalid date format. Please enter a date in the format MM dd yyyy.";
        }
    }

