public boolean canArrange(int[] arr, int k) {
        if (arr.length % 2 != 0) {
            return false;
        }

        int[] remainderCount = new int[k];
        for (int num : arr) {
            remainderCount[num % k]++;
        }

        for (int remainder = 0; remainder < k; remainder++) {
            if (remainderCount[remainder] > remainderCount[k - remainder]) {
                return false;
            }
        }

        return true;
    }

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    Map<Integer, Integer> count = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        count.put(remainder, count.getOrDefault(remainder, 0) + 1);
    }
    int elementsWithOddSum = count.getOrDefault(0, 0) % 2 == 1 ? count.get(0) : 0;
    if (elementsWithOddSum > n / 2 || n % 2 == 1) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        if (!count.containsKey(k - i) || count.get(i) != count.getOrDefault(k - i, 0)) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }

    Map<Integer, Integer> remainderCount = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        if (remainderCount.containsKey(remainder)) {
            remainderCount.put(remainder, remainderCount.get(remainder) + 1);
        } else {
            remainderCount.put(remainder, 1);
        }
    }

    for (int key : remainderCount.keySet()) {
        if (key == 0) {
            if (remainderCount.get(key) % 2 != 0) {
                return false;
            }
        } else if (key == k - key) {
            if (remainderCount.get(key) <= 1) {
                return false;
            }
        } else if (!remainderCount.containsKey(k - key)) {
            return false;
        }
    }

    return true;
}

