public String sortString(String s) {
    Queue<Character> minHeap = new PriorityQueue<>();
    Queue<Character> maxHeap = new PriorityQueue<>(Collections.reverseOrder());

    // Build heaps from the input string
    for (char c : s.toCharArray()) {
        minHeap.offer(c);
        maxHeap.offer(c);
    }

    StringBuilder result = new StringBuilder();
    char lastChar = '*'; // Dummy character to handle edge cases

    while (result.length() < s.length()) {
        // Choose and append the smallest character
        char minChar = minHeap.poll();
        if (lastChar != minChar) {
            result.append(minChar);
            lastChar = minChar;
        }

        // Choose and append the largest character (excluding the same last character)
        char maxChar = maxHeap.poll();
        if (!minChar.equals(maxChar) && lastChar != maxChar) {
            result.append(maxChar);
            lastChar = maxChar;
        }
    }

    return result.toString();
}

public static String sortString(String s) {
        // Base case: if the string is empty, return it as is
        if (s.isEmpty()) {
            return s;
        }

        // Split the string into two parts: one containing characters larger than the first character
        // and the other containing characters smaller than the first character
        String largerPart = s.substring(1);
        String smallerPart = "";

       for (char c : s.substring(1).toCharArray()) {
            if (c > s.charAt(0)) {
                largerPart = largerPart + c;
            } else {
                smallerPart = smallerPart + c;
            }
        }

        // Sort the smaller part and append it to the larger part
        String result = largerPart + StringSorter.sortString(smallerPart);

        // Swap the first and last characters if necessary
        int length = result.length();
        if (result.charAt(length - 1) < result.charAt(0)) {
            char temp = result.charAt(length - 1);
            result = result.substring(0, length - 1) + result.charAt(0) + temp;
        }

        return result;
    }

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[128];
    for (char c : s.toCharArray()) {
        count[c]++;
    }

    StringBuilder result = new StringBuilder();

    for (int i = 0; i < 128; i++) {
        while (count[i] > 0 && i <= result.charAt(result.length() - 1) - 'a') {
            result.append((char) (i + 'a'));
            count[i]--;
        }
    }

    for (int i = 127; i >= 0; i--) {
        while (count[i] > 0 && i >= result.charAt(result.length() - 1) - 'a') {
            result.append((char) (i + 'a'));
            count[i]--;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    char[] array = s.toCharArray();
    Arrays.sort(array);

    int i = 0; // Starting index
    int j = array.length - 1; // Ending index

    while (i <= j) {
        if (i == j) {
            result.append(array[i]);
            break;
        }
        result.append(array[i]);
        result.append(array[j]);
        i++;
        j--;
    }
    return result.toString();
}

public String sortString(String s) {
    StringBuilder result = new StringBuilder();
    char[] chars = s.toCharArray();
    int left = 0, right = chars.length - 1;

    // Helper to find the minimum character in the array
    Comparator<Character> asc = (c1, c2) -> c1 - c2;

    while (left <= right) {
        // Find the smallest character
        int minIndex = left;
        for (int i = left; i <= right; i++) {
            if (asc.compare(chars[i], chars[minIndex]) < 0) {
                minIndex = i;
            }
        }
        result.append(chars[minIndex]);
        chars[minIndex] = '\0'; // Mark the character as used

        // Find the largest character less than the current smallest
        int maxIndex = right;
        for (int i = right; i >= left; i--) {
            if (asc.compare(chars[i], chars[maxIndex]) > 0) {
                maxIndex = i;
            }
        }
        if (maxIndex != left) { // To avoid appending the same character again
            result.append(chars[maxIndex]);
            chars[maxIndex] = '\0'; // Mark the character as used
        }

        // Update the left and right pointers
        left++;
        right--;
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] A) {
        int sum = Arrays.stream(A).sum();
        int avg = sum / A.length;
        if (avg * A.length != sum) {
            return false;
        }
        int target = sum / 2;
        int memo[] = new int[A.length + 1][target + 1];
        for (int i = 0; i <= target; i++) {
            memo[0][i] = true;
        }
        Arrays.fill(memo[1], false);

        for (int i = 1; i < A.length; i++) {
            int val = A[i];
            for (int j = target; j >= val; j--) {
                memo[i + 1][j] = memo[i][j] || memo[i][j - val];
            }
        }
        return memo[A.length][target];
    }

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the total sum of the array
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // Check if the total sum is odd, if so, it's impossible to split the array
    if (totalSum % 2 != 0) return false;

    // Determine the average of both subarrays
    double avg = totalSum / 2.0;

    // Iterate through the array to find a possible split
    for (int i = 1; i < nums.length; i++) {
        // Check if the sum of the subarray before the current element is equal to the difference between the average and the current element
        if (nums[i] * (i + 1) == avg * nums.length - nums[i]) {
            return true;
        }
    }

    return false;
}

