public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i - 1];
    }

    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int prev1 = cost[0];
    int prev2 = cost[1];
    int minCost;

    for (int i = 2; i < n; i++) {
        minCost = Math.min(prev1, prev2) + cost[i];
        prev1 = prev2;
        prev2 = minCost;
    }

    return Math.min(prev1, prev2);
}

