        int code = Integer.parseInt(substring, 2); // Convert substring to an integer (base 2)
        if (!seen[code]) {
            seen[code] = true;
        } else {
            return false; // If the same substring is seen again, return false
        }
    }

    // Check if all substrings are seen
    for (boolean b : seen) {
        if (!b) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    int uniqueCodes = (1 << k); // Number of unique binary strings of length k
    boolean[] usedCodes = new boolean[uniqueCodes]; // Array to store used binary codes

    for (int i = 0; i + k <= s.length(); i++) {
        int code = Integer.parseInt(s.substring(i, i + k), 2); // Convert substring to integer
        if (usedCodes[code]) {
            return false; // If the code is already used, return false
        }
        usedCodes[code] = true; // Mark the code as used
    }

    return true; // All unique binary codes are found in the string
}

public boolean hasAllCodes(String s, int k) {

    // Generating the set of distinct substrings of length k from s
    Set<String> distinctSubstrings = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        distinctSubstrings.add(s.substring(i, i + k));
    }

    // Checking if the size of the set is equal to 2^k
    return distinctSubstrings.size() == (int)Math.pow(2, k);
}

