public int minInsertions(String s) {
    int balance = 0, insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') balance++;
        else {
            if (balance == 0) insertions++;
            balance--;
        }
    }

    // The remaining balancing need to be done with addition of ")
    return insertions + balance;
}

public int minInsertions(String s) {
    int len = s.length();
    if (len == 1) return 1;

    int minInsert = 0;
    int balance = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') balance++;
        else if (balance > 0) balance--;
        else if (balance == 0) {
            balance--;
            minInsert++;
        } else {
            minInsert++;
            balance--;
        }
    }

    if (balance == 1) minInsert++;
    return minInsert;
}

public int minInsertions(String s) {
    int left = 0; // Count of unmatched left brackets
    int result = 0; // Total number of insertion operations

    for (char c : s.toCharArray()) {
        if (c == '(') {
            left++;
        } else if (left > 0) {
            left--; // Found a matching right bracket for an unmatched left bracket
        } else {
            result++; // Add a left bracket to make the right bracket balanced
        }
    }

    return result + left; // Add the remaining unmatched left bracketsNeed to be added
}

public int minInsertions(String s) {
    int i = 0, j = s.length() - 1, balance = 0, ans = 0;

    // Move left pointer to find the first right parenthesis after any unbalanced left parentheses
    while (i < j && s.charAt(i) == '(') {
        i++;
    }

    // Move right pointer to find the last left parenthesis before any unbalanced right parentheses
    while (i < j && s.charAt(j) == ')') {
        j--;
    }

    // Calculate the minimum number of insertion operations required for matching pairs of parentheses
    for (; i <= j; i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (balance <= 0) {
                ans++;
            }
            balance--;
        }
    }

    // Add the total number of left parentheses (excluding those already part of a matching pair) to the answer
    ans += s.length() - (i + j) - balance - 1;

    return ans;
}

public int minInsertions(String s) {
        int open = 0, close = 0, res = 0, balance = 0;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (c == '(') {
                balance++;
                open++;
            } else {
                if (balance > 0) {
                    balance--;
                } else {
                    res++;
                    open++;
                }
            }
        }

        // All remaining '(' need to be inserted to balance the string
        res += open;

        return res;
    }

public static int minOperations(int n) {
        int totalSum = n * (n + 1) / 2;
        int sum = 1;
        for (int i = 0; i < n; i++) {
            totalSum -= sum;
            sum += 2 * i + 1;
        }
        return n / 2 * (totalSum / n) + (n % 2) * (n - totalSum % n); // Average + any remainder
    }

public int minOperations(int n) {
    int count = 0;
    for (int i = 0; i < n / 2; i++) {
        count += (2 * i + 1) - ((2 * n - 1) - (2 * i + 1));
    }
    return count;
}

public int minOperations(int n) {
        if (n == 1) return 0;
        if (n % 4 == 0) return n * (n - 1) / 2;
        if (n % 4 == 2) return n * (n - 1) / 2 + n / 2;
        if (n % 4 == 3) return n * (n - 1) / 2 + n / 3 - 2;
        return n * (n - 1) / 2 - 2;
    }

public int minOperations(int n) {
    int minOperations = 0;
    for (int i = 0; i < n / 2; i++) {
        int diff = 2 * i + 1;
        minOperations += Math.abs(diff);
    }
    return minOperations;
}

public int minOperations(int n) {
        // Initialize the sum of all elements in the array
        int sum = 0;
        for (int i = 0; i < n; i++) {
            sum += (2 * i) + 1;
        }
        int target = sum / n; // Target value for all elements in the array
        int count = 0; // Counter for the number of operations

        // Iterate through the array
        for (int i = 0; i < n; i++) {
            // Calculate the required operation to make the current element equal to the target
            if(!(i&1)) { // If the element is even
                count += Math.abs(target - (2 * i + 1)); // Calculate the absolute difference
            }
        }

        return count;
    }

