public int maxAbsoluteSum(int[] nums) {
        int n = nums.length;
        int minSum = 0;
        int currentSum = 0;
        int maxSum = 0;

        for (int i = 0; i < n; i++) {
            currentSum += nums[i];
            maxSum = Math.max(maxSum, currentSum);
            minSum = Math.min(minSum, currentSum);
        }

        return Math.max(maxSum, -minSum);
    }

public int maxAbsoluteSum(int[] nums) {
    int maxSub = Integer.MIN_VALUE, minSub = Integer.MAX_VALUE;
    int maxSoFar = 0;
    if(nums.length==0) return 0;
    for(int i=0; i<nums.length; i++){
        maxSub = Math.max(nums[i], maxSub+nums[i]);
        maxSoFar = Math.max(maxSub, maxSoFar);
        minSub = Math.min(nums[i], minSub+nums[i]);
        if(minSub > 0) minSub=0;
    }
    return Math.max(maxSoFar, -minSub);
}

public static int maxAbsoluteSum(int[] nums) {
        int minSum = 0, maxSum = 0;
        int maxAbsSum = 0;

        for (int num : nums) {
            minSum = Math.min(num, minSum + num);
            maxSum = Math.max(num, maxSum + num);
            maxAbsSum = Math.max(maxAbsSum, Math.max(Math.abs(minSum), Math.abs(maxSum)));
        }

        return maxAbsSum;
    }

public int maxAbsoluteSum(int[] nums) {
    int maxSum = Integer.MIN_VALUE;
    int minSum = Integer.MAX_VALUE;
    int currentSum = 0;
    int maxSubarrayStart = 0;
    int maxSubarrayEnd = -1;

    for (int i = 0; i < nums.length; i++) {
        currentSum += nums[i];

        if (currentSum > maxSum) {
            maxSum = currentSum;
            maxSubarrayStart = maxSubarrayEnd = i;
        } else if (currentSum < minSum) {
            minSum = currentSum;
            maxSubarrayEnd = i;
        }
    }

    return Math.max(maxSum - minSum, 0);
}

