        minSum = Math.min(minSum, num);
    }

    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
        int[] fib = {1, 1, 2, 3, 5, 8, 13, 21};
        int[] result = new int[8];
        int index = 7;

        while (k > 0) {
            if (k >= fib[index]) {
                result[index] = 1;
                k -= fib[index];
            } else {
                index--;
            }
        }

        return Arrays.stream(result).filter(x -> x == 1).sum();
    }

public int findMinFibonacciNumbers(int k) {
        if (k <= 2) {
            return k == 0 ? 0 : 1;
        }
        Arrays.sort(fib);

        int minFibs = 0;
        int index = fib.length - 1;

        while (k > 0) {
            while (index >= 0 && fib[index] > k) {
                index--;
            }
            if (index < 0) {
                break;
            }
            k -= fib[index];
            minFibs++;
        }

        return minFibs;
    }

public int findMinFibonacciNumbers(int k) {
        List<Integer> fibonacci_numbers = new ArrayList<>();
        int a = 1, b = 1;
        while (a <= k) {
            fibonacci_numbers.add(a);
            int temp = a + b;
            a = b;
            b = temp;
        }

        int sum = 0, count = 0;
        for (int i = fibonacci_numbers.size() - 1; i >= 0; i--) {
            while (sum + fibonacci_numbers.get(i) <= k) {
                sum += fibonacci_numbers.get(i);
                count++;
            }
        }
        return count;
    }

public int findMinFibonacciNumbers(int k) {
    int f1 = 1, f2 = 1;
    while (f2 <= k) {
        int fibSum = f1 + f2;
        if (fibSum == k) {
            return 2;
        }
        if (fibSum > k) {
            return 1;
        }
        f1 = f2;
        f2 = fibSum;
    }
    int count = 1;
    while (f1 < k) {
        k -= f1;
        count += 1;
    }
    return count + 1;
}

public int findMinFibonacciNumbers(int k) {
    int[] fibArray = {1, 1};
    while (true) {
        long nextFib = fibArray[fibArray.length - 1] + fibArray[fibArray.length - 2];
        if (nextFib > Integer.MAX_VALUE) {
            break;
        }
        fibArray[fibArray.length] = (int) nextFib;
    }

    int count = 0;
    for (int i = fibArray.length - 1; i >= 0 && k > 0; i--) {
        if (k >= fibArray[i]) {
            count++;
            k -= fibArray[i];
        }
    }

    return count;
}

