public String makeGood(String s) {
    String result = "";
    int l = 0, r = 0;

    while (r < s.length()) {
        if (l == r) {
            result += s.charAt(r++);
        } else if ((s.charAt(l) == Character.toLowerCase(s.charAt(r)) || s.charAt(l) == Character.toUpperCase(s.charAt(r)))) {
            l = r;
            r++;
        } else {
            result += s.charAt(l++);
        }
    }

    return result;
