        if ((current == 'a' && next == 'A') || (current == 'A' && next == 'a')) {
            sb.deleteCharAt(i);
            sb.deleteCharAt(i);
            i = Math.max(0, i - 2);
        } else {
            i++;
        }
    }
    return sb.toString();
}

