public int maxUniqueSplit(String s) {
    int count = 0, index = 0, uniqueCount = 0;
    List<String> uniqueSubstrings = new ArrayList<>();

    while (index < s.length()) {
        // Try to find a unique substring starting from index
        for (int len = uniqueCount; len <= s.length() - index; len++) {
            String currentSubstring = s.substring(index, index + len);
            if (!uniqueSubstrings.contains(currentSubstring)) {
                uniqueSubstrings.add(currentSubstring);
                count++;
                index += len;
                break;
            }
        }
        // If no unique substring is found with current uniqueCount length
        if (len == uniqueCount) {
            uniqueCount++;
        }
    }

    return count;
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    if (n == 0) return 0;

    boolean[][] dp = new boolean[n + 1][n + 1];
    dp[0][0] = true;

    Set<String> set = new HashSet<>();

    for (int i = 1; i <= n; i++) {
        dp[i][i] = true;
    }

    for (int len = 2; len <= n; len++) {
        for (int i = 1; i <= n - len + 1; i++) {
            int end = i + len - 1;
            if (dp[i - 1][end - 1] || s.substring(i - 1, end).equals(s.substring(end - len))) {
                dp[i][end] = true;
                set.add(s.substring(i - 1, end));
            }
            if (dp[i][end]) dp[i + 1][end] |= dp[i][end - 1];
        }
    }

    return set.size();
}

public int maxUniqueSplit(String s) {
    int maxUnique = 0;
    int n = s.length();
    List<Integer> positions = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        int hash = 0;
        boolean[] used = new boolean[26];
        boolean duplicate = false;
        for (int j = i; j < n; j++) {
            hash = (hash * 31 + (s.charAt(j) - 'a')) % 1000000007;
            if (used[s.charAt(j) - 'a']) {
                duplicate = true;
                break;
            }
            if (!duplicate) {
                used[s.charAt(j) - 'a'] = true;
            }
            positions.add(hash);
            if (duplicate) {
                break;
            }
        }
        if (!duplicate) {
            maxUnique++;
        }
    }
    return maxUnique;
}

