public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    while (n > 0) {
        if (k > 0) {
            sb.append((char) ('a' + (k - 1)));
            k--;
        } else {
            sb.append('a');
        }
        n--;
    }
    return sb.reverse().toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder smallString = new StringBuilder();
    for (int i = 0; i < n; i++) {
        while (true) {
            if (k >= 26 + i) {
                smallString.append((char) (96 + i));
                k -= 26 + i;
                break;
            } else if (k > i) {
                char charToUse = (char) (96 + i);
                smallString.append(charToUse);
                k--;
                break;
            } else {
                smallString.insert(0, (char) (96 + i));
                k--;
            }
        }
    }
    return smallString.toString();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a');

    k -= (n - 1) * 1;

    for (int i = 0; i < n; i++) {
        if (k >= 26) {
            result[i] = (char) ('a' + k - 26);
            k = 0;
        } else {
            result[i] = (char) ('a' + k);
            k = 0;
        }
    }

    return new String(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder smallestString = new StringBuilder "";

    // Edge case: if k is a multiple of 26 (base of alphabet), return "z" repeated n times
    if (k % 26 == 0) {
        for (int i = 0; i < n; i++) {
            smallestString.append('z');
        }
        return smallestString.toString();
    }

    // Calculate the maximum 'a' characters in the string
    int maxAs = k / 26;

    // Append 'a' characters to the string
    for (int i = 0; i < maxAs; i++) {
        smallestString.append('a');
    }

    // Calculate the remaining value to be distributed among 'z' characters
    int remainingValue = k % 26;

    // Append 'z' characters to the string, each with a value of remainingValue
    for (int i = 0; i < remainingValue; i++) {
        smallestString.append('z');
    }

    return smallestString.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < n; i++) {
        int remainder = k % 26;
        k -= remainder;
        sb.append((char) ('a' + remainder));
    }
    return sb.toString();
