public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        Queue<Integer> queue = new LinkedList<>();
        queue.offer(low);

        while (!queue.isEmpty()) {
            Integer num = queue.poll();
            if (num < low) {
                continue;
            }
            if (num > high) {
                break;
            }
            result.add(num);

            int lastDigit = num % 10;
            int nextDigit = lastDigit + 1;
            int prevDigit = lastDigit - 1;

            if (nextDigit < 10 && !result.contains(num * 10 + nextDigit)) {
                queue.offer(num * 10 + nextDigit);
            }
            if (prevDigit >= 0 && !result.contains(num * 10 + prevDigit)) {
                queue.offer(num * 10 + prevDigit);
            }
        }

        return result;
    }

