public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    Queue<Integer> queue = new LinkedList<>();
    if (low <= 1) queue.add(0); // Starting point

    // Perform BFS to find stepping numbers
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current >= low && current <= high) steppingNumbers.add(current);
        int lastDigit = current % 10;
        if (lastDigit >  0 && queue.add(current * 10 + (lastDigit - 1))) {
            int diff = current - (lastDigit - 1) * 10;
            if (diff >= low && diff <= high) {
                steppingNumbers.add(diff);
            }
        }
        if (lastDigit < 9 && queue.add(current * 10 + (lastDigit + 1))) {
            int diff = current + (lastDigit + 1) * 10;
            if (diff >= low && diff <= high) {
                steppingNumbers.add(diff);
            }
        }
    }

    return steppingNumbers;
}

