public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] leftSmallest = new int[n];
    int[] rightSmallest = new int[n];
    Stack<Integer> stack = new Stack<>();

    // Find the left smallest element for each index
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        leftSmallest[i] = (stack.isEmpty()) ? -1 : stack.peek();
        stack.push(i);
    }

    // Reset stack for right smallest element for each index
    stack.clear();

    // Find the right smallest element for each index
    for (int i = n - 1; i >= 0; i--) {
        while (!stack.isEmpty() && heights[stack.peek()] >= heights[i]) {
            stack.pop();
        }
        rightSmallest[i] = (stack.isEmpty()) ? n : stack.peek();
        stack.push(i);
    }

    int maxArea = 0;
    // Calculate maximum area by multiplying width and height for each bar
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, (rightSmallest[i] - leftSmallest[i] - 1) * heights[i]);
    }

    return maxArea;
}

