    // Array of left boundaries
    for (int i = 0; i < n; i++) {
        int j = i-1;
        while (j >= 0 && heights[j] >= heights[i]) j--;
        left[i] = j+1;
    }

    // Array of right boundaries
    for (int i = 0; i < n; i++) {
        int j = i+1;
        while (j < n && heights[j] >= heights[i]) j++;
        right[i] = j-1;
    }

    // Calculate the area for each bar and update maxArea
    for (int i = 0; i < n; i++) 
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] + 1));

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
