        int leftBound[] = new int[heights.length];
        int rightBound[] = new int[heights.length];
        leftBound[0] = -1;
        rightBound[heights.length - 1] = heights.length;

        for (int i = 1; i < heights.length; i++) {
            int left = i - 1;
            while (left >= 0 && heights[left] >= heights[i]) left--;
            leftBound[i] = left;
        }

        for (int j = heights.length - 2; j >= 0; j--) {
            int right = j + 1;
            while (right < heights.length && heights[right] >= heights[j]) right++;
            rightBound[j] = right;
        }

        for (int k = 0; k < heights.length; k++) {
            maxArea = Math.max(maxArea, heights[k] * (rightBound[k] - leftBound[k] - 1));
        }

        return maxArea;
    }

