public static int findSmallestInteger(int n) {
    if (n == 0) return -1;

    // Step 1: Convert the integer to a character array
    char[] digits = String.valueOf(n).toCharArray();
    int div = -1;

    // Step 2: Find the first position where the digit to the right is greater than the digit to its left
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            div = i;
            break;
        }
    }

    if (div == -1) {
        // If no such position is found, it's not possible to get a smaller rearrangement
        return -1;
    }

    // Step 3: Find the smallest digit to the right that is greater than digits[div]
    int smallestGreater = div + 1;
    for (int i = digits.length - 1; i > div; i--) {
        if (digits[i] > digits[div]) {
            if (digits[smallestGreater] > digits[i]) {
                smallestGreater = i;
            }
        }
    }

    // Step 4: Swap digits[div] and digits[smallestGreater]
    char temp = digits[div];
    digits[div] = digits[smallestGreater];
    digits[smallestGreater] = temp;

    // Step 5: Sort the remaining digits to get the smallest possible rearrangement
    Arrays.sort(digits, div + 1, digits.length);

    // Step 6: Convert the character array back to an integer
    return Integer.parseInt(String.valueOf(digits));
}

