        uniqueElements.add(num);
    }
    int sum = 0;
    for (int num : uniqueElements) {
        sum += num;
    }
    return sum;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueElements = new HashSet<>(Arrays.asList(nums));
    return uniqueElements.stream().mapToInt(Integer::intValue).sum();
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

