public static int minPerfectSquareSum(int n) {
    int dp[] = new int[n + 1];
    dp[0] = 0; // Base case: 0 perfect squares sum to the smallest number, which is 0

    for (var i = 1; i <= n; i++) {
        dp[i] = i; // Initially, assume the optimal solution without a perfect square is to add the number itself
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1); // Update the dp table based on the optimal sum found
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int num = (int) Math.sqrt(n);
    int[][] dp = new int[num + 1][n + 1];
    for (int i = 0; i <= num; i++) {
        for (int j = 0; j <= n; j++) {
            if (j == 0)
                dp[i][j] = 0;
            else {
                dp[i][j] = dp[i][j - i * i];
                if (dp[i][j] > 0)
                    dp[i][j] += 1;
                else
                    dp[i][j] = dp[i - 1][j];
            }
        }
    }
    return dp[num][n];
}

